-- Real customer import: CUSTOMERDATAFORCRM.xlsx (supplied by AKAI via Manus).
-- 206 rows: 102 under "SALE AGENT: HARRIS" (display name Haris) and 104 under "SALE AGENT: DANIYAL".
-- Rules from PROJECT_RULES.md:
--   * every row is an ordinary ACTIVE customer; no internal accounts; data_complete = false
--   * customer_type = OTHER; a keyword guess goes only into customer_type_suggestion
--   * Title Case business_name, UPPERCASE normalized_name
--   * import_key = workbook hash + source row, so the import is idempotent
--   * exact/near duplicates (>= 90% name similarity) are flagged for manual review, never merged
--   * area codes use the workbook abbreviation as name/town until an Admin fills them in
-- Sales Agent logins do not exist yet. Each customer keeps import_agent_alias (HARIS / DANIYAL);
-- when a Sales Agent with that agent code is created, a trigger assigns their customers.

alter table public.customers add column if not exists import_agent_alias text;
create index if not exists customers_import_agent_alias_idx on public.customers (import_agent_alias) where assigned_agent_id is null;

create or replace function public.canonical_agent_alias(p_value text)
returns text language sql immutable set search_path = public as $$
  select case when upper(trim(p_value)) in ('HARRIS', 'HARIS') then 'HARIS' else nullif(upper(trim(p_value)), '') end;
$$;

create or replace function public.assign_imported_customers_to_agent()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.customers c
     set assigned_agent_id = new.id, updated_at = now()
   where c.assigned_agent_id is null
     and c.import_agent_alias is not null
     and c.import_agent_alias = public.canonical_agent_alias(new.agent_code);
  return new;
end;
$$;
revoke all on function public.assign_imported_customers_to_agent() from public, anon, authenticated;
drop trigger if exists sales_agents_assign_imported_customers on public.sales_agents;
create trigger sales_agents_assign_imported_customers
  after insert or update of agent_code on public.sales_agents
  for each row execute function public.assign_imported_customers_to_agent();


on conflict (code) do nothing;

on conflict (import_key) do nothing;

-- Agents created before this migration: assign their customers now.
update public.customers c
   set assigned_agent_id = sa.id, updated_at = now()
  from public.sales_agents sa
 where c.assigned_agent_id is null
   and c.import_agent_alias = public.canonical_agent_alias(sa.agent_code);
